// ─── File: EventStyleDemo.java ───
// Runnable demo: Notification vs State Transfer vs fat-event anti-pattern.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class EventStyleDemo {

    private static final Logger log = Logger.getLogger("eventstyle");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferApi api = new TransferApi();
        TransferEventFactory factory = new TransferEventFactory();

        log.info("===== EVENT NOTIFICATION (minimal; consumer calls back) =====");
        TransferNotificationEvent notif = factory.notification("T-123", "SAV2001");
        NotificationViaNotification c1 = new NotificationViaNotification(api);
        c1.onEvent(notif);                 // calls back for details
        api.setDown(true);
        c1.onEvent(notif);                 // producer down → cannot get details

        log.info("===== EVENT-CARRIED STATE TRANSFER (data in event; no callback) =====");
        TransferStateTransferEvent st = factory.stateTransfer("T-123", "SAV2001", "BENEF-77", new BigDecimal("50000"));
        NotificationViaStateTransfer c2 = new NotificationViaStateTransfer();
        c2.onEvent(st);                    // acts immediately, even with producer down

        log.info("===== FAT / GOD EVENT (anti-pattern) =====");
        TransferFatEvent fat = factory.fatEvent("T-123", "SAV2001", "BENEF-77",
                new BigDecimal("50000"), "LEDGER-ab12", 2);
        log.severe(() -> "[FAT] god event leaks internals: internalRef=" + fat.internalRef
                + " riskBucket=" + fat.riskBucket + " — couples consumers to producer internals (AVOID)");
    }
}

// ─── events/TransferNotificationEvent.java — minimal ───
class TransferNotificationEvent {
    final String eventId; final String type = "TransferCompleted";
    final String transferId; final String accountId; final String detailsLink;
    TransferNotificationEvent(String eventId, String transferId, String accountId) {
        this.eventId = eventId; this.transferId = transferId; this.accountId = accountId;
        this.detailsLink = "/api/v1/transfers/" + transferId;   // consumer fetches details here
    }
}

// ─── events/TransferStateTransferEvent.java — curated data ───
class TransferStateTransferEvent {
    final String eventId; final String transferId; final String accountId;
    final String beneficiary; final BigDecimal amount; final int schemaVersion = 1;
    TransferStateTransferEvent(String eventId, String transferId, String accountId,
                               String beneficiary, BigDecimal amount) {
        this.eventId = eventId; this.transferId = transferId; this.accountId = accountId;
        this.beneficiary = beneficiary; this.amount = amount;
    }
}

// ─── events/TransferFatEvent.java — ANTI-PATTERN (do not do this) ───
class TransferFatEvent {
    final String transferId; final String accountId; final String beneficiary; final BigDecimal amount;
    final String internalRef;   // internal-only, must not be here
    final int riskBucket;        // internal-only, must not be here
    TransferFatEvent(String transferId, String accountId, String beneficiary, BigDecimal amount,
                     String internalRef, int riskBucket) {
        this.transferId = transferId; this.accountId = accountId; this.beneficiary = beneficiary;
        this.amount = amount; this.internalRef = internalRef; this.riskBucket = riskBucket;
    }
}

// ─── producer/TransferEventFactory.java ───
class TransferEventFactory {
    TransferNotificationEvent notification(String transferId, String accountId) {
        return new TransferNotificationEvent("EVT-" + id(), transferId, accountId);
    }
    TransferStateTransferEvent stateTransfer(String transferId, String accountId, String beneficiary, BigDecimal amount) {
        return new TransferStateTransferEvent("EVT-" + id(), transferId, accountId, beneficiary, amount);
    }
    TransferFatEvent fatEvent(String transferId, String accountId, String beneficiary, BigDecimal amount,
                              String internalRef, int riskBucket) {
        return new TransferFatEvent(transferId, accountId, beneficiary, amount, internalRef, riskBucket);
    }
    private String id() { return UUID.randomUUID().toString().substring(0, 8); }
}

// ─── producer/TransferApi.java — callback target for Event Notification ───
class TransferApi {
    private boolean down = false;
    void setDown(boolean down) { this.down = down; }
    // returns [beneficiary, amount] or null if producer is down
    String[] fetchDetails(String transferId) {
        if (down) return null;
        return new String[]{"BENEF-77", "50000"};
    }
}

// ─── consumer/NotificationViaNotification.java ───
class NotificationViaNotification {
    private static final Logger log = Logger.getLogger("eventstyle");
    private final TransferApi api;
    NotificationViaNotification(TransferApi api) { this.api = api; }
    void onEvent(TransferNotificationEvent e) {
        String[] details = api.fetchDetails(e.transferId);   // synchronous callback — runtime coupling
        if (details == null) {
            log.severe(() -> "[NOTIFY-N] producer DOWN — cannot fetch details for " + e.transferId + " → SMS blocked");
            return;
        }
        log.info(() -> "[NOTIFY-N] fetched details, SMS: Rs." + details[1] + " to " + details[0]);
    }
}

// ─── consumer/NotificationViaStateTransfer.java ───
class NotificationViaStateTransfer {
    private static final Logger log = Logger.getLogger("eventstyle");
    void onEvent(TransferStateTransferEvent e) {
        // No callback — all needed data is in the event → autonomous & resilient.
        log.info(() -> "[NOTIFY-S] SMS immediately (no callback): Rs." + e.amount + " to " + e.beneficiary);
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
